const raw = $input.first().json;
const body = raw.body ?? raw;
const block = body.attachments?.[0]?.text ?? body;
const devices = [];
const offline = [];
const seenMac = new Set();

const pushUnique = (list, item) => {
  const k = String(item.mac || '').toLowerCase();
  if (!k || k === '?' || seenMac.has(k)) return;
  seenMac.add(k);
  list.push(item);
};

for (const d of block.new_devices || []) {
  pushUnique(devices, {
    name: d['Device name'] || d.devName || 'Bilinmeyen',
    mac: d.MAC || d.eveMac || '?',
    ip: d.IP || d.eveIp || '?',
    vendor: d.Vendor || d.devVendor || '',
    type: d.Type || d.devType || '',
  });
}
for (const d of block.down_devices || []) {
  pushUnique(offline, {
    name: d.devName || d['Device name'] || 'Bilinmeyen',
    mac: d.eveMac || d.MAC || '?',
    ip: d.eveIp || d.IP || '?',
  });
}
for (const ev of block.events || []) {
  const type = String(ev.eveEventType || ev['Event type'] || ev.type || '');
  const mac = ev.eveMac || ev.MAC || '?';
  const ip = ev.eveIp || ev.IP || '?';
  const name = ev.devName || ev['Device name'] || 'Bilinmeyen';
  if (/new device/i.test(type)) {
    pushUnique(devices, { name, mac, ip, vendor: ev.devVendor || ev.Vendor || '', type: ev.devType || ev.Type || '' });
  } else if (/disconnect/i.test(type)) {
    pushUnique(offline, { name, mac, ip });
  }
}

if (devices.length === 0 && offline.length === 0) return [];

const now = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const panel = '__PANEL_PROTOCOL__://devices.__LAN_DOMAIN__';
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const chunks = [];

if (devices.length) {
  const head = devices.length === 1 ? 'Ev ağında yeni cihaz tespit edildi.' : `${devices.length} yeni cihaz tespit edildi — ev ağı.`;
  chunks.push(`<b>${esc(head)}</b>`);
  devices.forEach((d, i) => {
    const title = devices.length === 1 ? d.name : `${i + 1}. ${d.name}`;
    const meta = [d.type, d.vendor].filter(Boolean).join(' · ');
    let blk = `<b>${esc(title)}</b>\nIP: <code>${esc(d.ip)}</code>\nMAC: <code>${esc(d.mac)}</code>`;
    if (meta) blk += `\nTür: ${esc(meta)}`;
    chunks.push(blk);
  });
}

if (offline.length) {
  chunks.push(`<b>${offline.length === 1 ? 'Ev ağında cihaz offline oldu.' : `${offline.length} cihaz offline — ev ağı.`}</b>`);
  offline.forEach((d) => {
    chunks.push(`${esc(d.name)} — <code>${esc(d.ip)}</code> · <code>${esc(d.mac)}</code>`);
  });
}

chunks.push(`<b>Ne yapmalı?</b>\n• Panel: ${esc(panel)}`);

return [{ json: { text: `<b>📋 Pi Gateway · Ağ</b>\n${esc(now)}\n\n${chunks.join('\n\n')}\n\n<i>Events tabanlı — işlenmiş olay tekrar bildirilmez.</i>`, parse_mode: 'HTML' } }];
